// src/theme.css: the theme's tokens (docs/design/look.md §3) as CSS variables the app kit's
// styles use, with the brand colour's changes on top and the ux file's density.
import {
  type Mode,
  type ThemeIR,
  type Tokens,
  themeNamed,
  tokensOf,
  type UxIR,
} from "@smithable/core";
import { brandColors } from "./brand.js";

const HEADER =
  "/* Generated by Smithable from smithable.ux.yml. Do not edit: this file is overwritten on every change. */\n";

/** Control and row sizes per density; touch screens always get 44 px targets. */
const DENSITY = {
  comfortable: { control: "2.75rem", row: "4rem", cell: "1rem", card: "1.5rem" },
  compact: { control: "2.25rem", row: "3.25rem", cell: "0.75rem", card: "1.25rem" },
};

/** Fonts hosted by the app itself (Fontsource, OFL); the package is added to package.json. */
export const FONT_PACKAGES: Record<string, string> = {
  Inter: "@fontsource-variable/inter",
  "Nunito Sans": "@fontsource-variable/nunito-sans",
  "Source Sans 3": "@fontsource-variable/source-sans-3",
};

/** The theme the ux file names, among the built-ins and the project's own. */
export function themeOf(ux: UxIR, themes: readonly ThemeIR[] = []): ThemeIR {
  const theme = themeNamed(ux.theme.preset, themes) ?? themeNamed("modern");
  if (!theme) throw new Error("No built-in theme");
  return theme;
}

/** The font the app uses: the brand's, or the theme's. */
export function themeFont(ux: UxIR, themes: readonly ThemeIR[] = []): string {
  return ux.theme.font ?? themeOf(ux, themes).font;
}

/** The theme's colour tokens in one mode, with a brand colour applied when there is one. */
function tokens(ux: UxIR, theme: ThemeIR, mode: Mode): Tokens {
  return tokensOf(theme, mode, ux.theme.primary ? brandColors(ux.theme.primary, theme, mode) : {});
}

export function themeCss(ux: UxIR, themes: readonly ThemeIR[] = []): string {
  const theme = themeOf(ux, themes);
  const font = themeFont(ux, themes);
  const density = DENSITY[ux.theme.density];
  const block = (values: Record<string, string>, indent: string) =>
    Object.entries(values)
      .map(([k, v]) => `${indent}--${k}: ${v};`)
      .join("\n");
  return `${HEADER}@import "${FONT_PACKAGES[font]}";

/* Theme: ${theme.name}${ux.theme.primary ? `, brand colour ${ux.theme.primary}` : ""}, font ${font}, ${ux.theme.density} */
:root {
${block(tokens(ux, theme, "light"), "  ")}
  --radius: ${theme.radius};
  --card-shadow: ${theme.shadow};
  --font-body: "${font} Variable", ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  --control-height: ${density.control};
  --row-height: ${density.row};
  --cell-padding: ${density.cell};
  --card-padding: ${density.card};
}

/* Touch screens get 44 px targets whatever the density. */
@media (pointer: coarse) {
  :root {
    --control-height: 2.75rem;
  }
}

@media (prefers-color-scheme: dark) {
  :root {
${block(tokens(ux, theme, "dark"), "    ")}
  }
}
`;
}
